import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,a1 as e,A as p,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"使用 PySimpleGUI 轻松为程序和脚本增加 GUI | LCTT x X-CMD","titleTemplate":false,"description":"使用 PySimpleGUI 轻松为程序和脚本增加 GUI | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 PySimpleGUI 轻松为程序和脚本增加 GUI | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 PySimpleGUI 轻松为程序和脚本增加 GUI | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180829 Add GUIs to your programs and scripts easily with PySimpleGUI","title":"使用 PySimpleGUI 轻松为程序和脚本增加 GUI","tag":"201809","desc":""},"relativePath":"201809/20180829 Add GUIs to your programs and scripts easily with PySimpleGUI.md","filePath":"[post].md"}'),u={name:"201809/20180829 Add GUIs to your programs and scripts easily with PySimpleGUI.md"};function h(g,s,c,b,m,k){const n=o("Link");return r(),d("div",null,[s[26]||(s[26]=l('<h1 id="使用-pysimplegui-轻松为程序和脚本增加-gui" tabindex="-1">使用 PySimpleGUI 轻松为程序和脚本增加 GUI <a class="header-anchor" href="#使用-pysimplegui-轻松为程序和脚本增加-gui" aria-label="Permalink to “使用 PySimpleGUI 轻松为程序和脚本增加 GUI”">​</a></h1><blockquote><p>五分钟创建定制 GUI。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/web_browser_desktop_devlopment_design_system_computer.jpg?itok=pfqRrJgh" alt=""></p><p>对于 <code>.exe</code> 类型的程序文件，我们可以通过双击鼠标左键打开；但对于 <code>.py</code> 类型的 Python 程序，几乎不会有人尝试同样的操作。对于一个（非程序员类型的）典型用户，他们双击打开 <code>.exe</code> 文件时预期弹出一个可以交互的窗体。基于 Tkinter，可以通过<ruby>标准 Python 安装<rt>standard Python installations</rt></ruby>的方式提供 GUI，但很多程序都不太可能这样做。</p><p>如果打开 Python 程序并进入 GUI 界面变得如此容易，以至于真正的初学者也可以掌握，会怎样呢？会有人感兴趣并使用吗？这个问题不好回答，因为直到今天创建自定义 GUI 布局仍不是件容易的事情。</p><p>在为程序或脚本增加 GUI 这件事上，似乎存在能力的“错配”。（缺乏这方面能力的）真正的初学者被迫只能使用命令行方式，而很多（具备这方面能力的）高级程序员却不愿意花时间创建一个 Tkinter GUI。</p><h3 id="gui-框架" tabindex="-1">GUI 框架 <a class="header-anchor" href="#gui-框架" aria-label="Permalink to “GUI 框架”">​</a></h3><p>Python 的 GUI 框架并不少，其中 Tkinter，wxPython，Qt 和 Kivy 是几种比较主流的框架。此外，还有不少在上述框架基础上封装的简化框架，例如 EasyGUI，PyGUI 和 Pyforms 等。</p><p>但问题在于，对于初学者（这里是指编程经验不超过 6 个月的用户）而言，即使是最简单的主流框架，他们也无从下手；他们也可以选择封装过的（简化）框架，但仍难以甚至无法创建自定义 GUI <ruby>布局<rt>layout</rt></ruby>。即便学会了某种（简化）框架，也需要编写连篇累牍的代码。</p>',9)),i("p",null,[e(n,{href:"https://github.com/MikeTheWatchGuy/PySimpleGUI"},{default:p(()=>[...s[0]||(s[0]=[a("PySimpleGUI",-1)])]),_:1}),s[1]||(s[1]=a(" 尝试解决上述 GUI 难题，它提供了一种简单明了、易于理解、方便自定义的 GUI 接口。如果使用 PySimpleGUI，很多复杂的 GUI 也仅需不到 20 行代码。",-1))]),s[27]||(s[27]=l('<h3 id="秘诀" tabindex="-1">秘诀 <a class="header-anchor" href="#秘诀" aria-label="Permalink to “秘诀”">​</a></h3><p>PySimpleGUI 极为适合初学者的秘诀在于，它已经包含了绝大多数原本需要用户编写的代码。PySimpleGUI 会处理按钮<ruby>回调<rt>callback</rt></ruby>，无需用户编写代码。对于初学者，在几周内掌握函数的概念已经不容易了，要求其理解回调函数似乎有些强人所难。</p><p>在大部分 GUI 框架中，布局 GUI <ruby>小部件<rt>widgets</rt></ruby>通常需要写一些代码，每个小部件至少 1-2 行。PySimpleGUI 使用了 “auto-packer” 技术，可以自动创建布局。因而，布局 GUI 窗口不再需要 pack 或 grid 系统。</p><p>（LCTT 译注：这里提到的 pack 和 grid 都是 Tkinter 的布局管理器，另外一种叫做 place 。）</p><p>最后，PySimpleGUI 框架编写中有效地利用了 Python 语言特性，降低用户代码量并简化 GUI 数据返回的方式。在<ruby>窗体<rt>form</rt></ruby>布局中创建小部件时，小部件会被部署到对应的布局中，无需额外的代码。</p><h3 id="gui-是什么" tabindex="-1">GUI 是什么？ <a class="header-anchor" href="#gui-是什么" aria-label="Permalink to “GUI 是什么？”">​</a></h3><p>绝大多数 GUI 只完成一件事情：收集用户数据并返回。在程序员看来，可以归纳为如下的函数调用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>button, values = GUI_Display(gui_layout)</span></span></code></pre></div><p>绝大多数 GUI 支持的用户行为包括鼠标点击（例如，“确认”，“取消”，“保存”，“是”和“否”等）和内容输入。GUI 本质上可以归结为一行代码。</p><p>这也正是 PySimpleGUI （的简单 GUI 模式）的工作原理。当执行命令显示 GUI 后，除非点击鼠标关闭窗体，否则不会执行任何代码。</p><p>当然还有更复杂的 GUI，其中鼠标点击后窗口并不关闭；例如，机器人的远程控制界面，聊天窗口等。这类复杂的窗体也可以用 PySimpleGUI 创建。</p><h3 id="快速创建-gui" tabindex="-1">快速创建 GUI <a class="header-anchor" href="#快速创建-gui" aria-label="Permalink to “快速创建 GUI”">​</a></h3>',12)),i("p",null,[s[3]||(s[3]=a("PySimpleGUI 什么时候有用呢？显然，是你需要 GUI 的时候。仅需不超过 5 分钟，就可以让你创建并尝试 GUI。最便捷的 GUI 创建方式就是从 ",-1)),e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/cookbook/"},{default:p(()=>[...s[2]||(s[2]=[a("PySimpleGUI 经典实例",-1)])]),_:1}),s[4]||(s[4]=a("中拷贝一份代码。具体操作流程如下：",-1))]),s[28]||(s[28]=l(`<ul><li>找到一个与你需求最接近的 GUI</li><li>从经典实例中拷贝代码</li><li>粘贴到 IDE 中并运行</li></ul><p>下面我们看一下书中的第一个<ruby>经典实例<rt>recipe</rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Very basic form.  Return values as a list</span></span>
<span class="line"><span>form = sg.FlexForm(&#39;Simple data entry form&#39;)  # begin with a blank form</span></span>
<span class="line"><span></span></span>
<span class="line"><span>layout = [</span></span>
<span class="line"><span>          [sg.Text(&#39;Please enter your Name, Address, Phone&#39;)],</span></span>
<span class="line"><span>          [sg.Text(&#39;Name&#39;, size=(15, 1)), sg.InputText(&#39;name&#39;)],</span></span>
<span class="line"><span>          [sg.Text(&#39;Address&#39;, size=(15, 1)), sg.InputText(&#39;address&#39;)],</span></span>
<span class="line"><span>          [sg.Text(&#39;Phone&#39;, size=(15, 1)), sg.InputText(&#39;phone&#39;)],</span></span>
<span class="line"><span>          [sg.Submit(), sg.Cancel()]</span></span>
<span class="line"><span>         ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(button, values[0], values[1], values[2])</span></span></code></pre></div><p>运行后会打开一个大小适中的窗体。</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui_cookbook-form.jpg" alt=""></p><p>如果你只是想收集一些字符串类型的值，拷贝上述经典实例中的代码，稍作修改即可满足你的需求。</p><p>你甚至可以只用 5 行代码创建一个自定义 GUI 布局。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form = sg.FlexForm(&#39;My first GUI&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>layout = [ [sg.Text(&#39;Enter your name&#39;), sg.InputText()],</span></span>
<span class="line"><span>           [sg.OK()] ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>button, (name,) = form.LayoutAndRead(layout)</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-5-line-form.jpg" alt=""></p><h3 id="_5-分钟内创建一个自定义-gui" tabindex="-1">5 分钟内创建一个自定义 GUI <a class="header-anchor" href="#_5-分钟内创建一个自定义-gui" aria-label="Permalink to “5 分钟内创建一个自定义 GUI”">​</a></h3><p>在简单布局的基础上，通过修改经典实例中的代码，5 分钟内即可使用 PySimpleGUI 创建自定义布局。</p><p>在 PySimpleGUI 中，<ruby>小部件<rt>widgets</rt></ruby>被称为<ruby>元素<rt>elements</rt></ruby>。元素的名称与编码中使用的名称保持一致。</p><p>（LCTT 译注：Tkinter 中使用小部件这个词）</p><h4 id="核心元素" tabindex="-1">核心元素 <a class="header-anchor" href="#核心元素" aria-label="Permalink to “核心元素”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Text</span></span>
<span class="line"><span>InputText</span></span>
<span class="line"><span>Multiline</span></span>
<span class="line"><span>InputCombo</span></span>
<span class="line"><span>Listbox</span></span>
<span class="line"><span>Radio</span></span>
<span class="line"><span>Checkbox</span></span>
<span class="line"><span>Spin</span></span>
<span class="line"><span>Output</span></span>
<span class="line"><span>SimpleButton</span></span>
<span class="line"><span>RealtimeButton</span></span>
<span class="line"><span>ReadFormButton</span></span>
<span class="line"><span>ProgressBar</span></span>
<span class="line"><span>Image</span></span>
<span class="line"><span>Slider</span></span>
<span class="line"><span>Column</span></span></code></pre></div><h4 id="元素简写" tabindex="-1">元素简写 <a class="header-anchor" href="#元素简写" aria-label="Permalink to “元素简写”">​</a></h4><p>PySimpleGUI 还包含两种元素简写方式。一种是元素类型名称简写，例如 <code>T</code> 用作 <code>Text</code> 的简写；另一种是元素参数被配置了默认值，你可以无需指定所有参数，例如 <code>Submit</code> 按钮默认的文本就是 “Submit”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>T = Text</span></span>
<span class="line"><span>Txt = Text</span></span>
<span class="line"><span>In = InputText</span></span>
<span class="line"><span>Input = IntputText</span></span>
<span class="line"><span>Combo = InputCombo</span></span>
<span class="line"><span>DropDown = InputCombo</span></span>
<span class="line"><span>Drop = InputCombo</span></span></code></pre></div><p>（LCTT 译注：第一种简写就是 Python 类的别名，第二种简写是在返回元素对象的 Python 函数定义时指定了参数的默认值）</p><h4 id="按钮简写" tabindex="-1">按钮简写 <a class="header-anchor" href="#按钮简写" aria-label="Permalink to “按钮简写”">​</a></h4><p>一些通用按钮具有简写实现，包括：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FolderBrowse</span></span>
<span class="line"><span>FileBrowse</span></span>
<span class="line"><span>FileSaveAs</span></span>
<span class="line"><span>Save</span></span>
<span class="line"><span>Submit</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>Ok （LCTT 译注：这里 \`k\` 是小写）</span></span>
<span class="line"><span>Cancel</span></span>
<span class="line"><span>Quit</span></span>
<span class="line"><span>Exit</span></span>
<span class="line"><span>Yes</span></span>
<span class="line"><span>No</span></span></code></pre></div><p>此外，还有通用按钮功能对应的简写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SimpleButton</span></span>
<span class="line"><span>ReadFormButton</span></span>
<span class="line"><span>RealtimeButton</span></span></code></pre></div><p>（LCTT 译注：其实就是返回 <code>Button</code> 类实例的函数）</p><p>上面就是 PySimpleGUI 支持的全部元素。如果不在上述列表之中，就不会在你的窗口布局中生效。</p><p>（LCTT 译注：上述都是 PySimpleGUI 的类名、类别名或返回实例的函数，自然只能使用列表内的。）</p><h4 id="gui-设计模式" tabindex="-1">GUI 设计模式 <a class="header-anchor" href="#gui-设计模式" aria-label="Permalink to “GUI 设计模式”">​</a></h4><p>对于 GUI 程序，创建并展示窗口的调用大同小异，差异在于元素的布局。</p><p>设计模式代码与上面的例子基本一致，只是移除了布局：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form = sg.FlexForm(&#39;Simple data entry form&#39;)</span></span>
<span class="line"><span># Define your form here (it&#39;s a list of lists)</span></span>
<span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span></code></pre></div><p>（LCTT 译注：这段代码无法运行，只是为了说明每个程序都会用到的设计模式。）</p><p>对于绝大多数 GUI，编码流程如下：</p><ul><li>创建窗体对象</li><li>以“列表的列表”的形式定义 GUI</li><li>展示 GUI 并获取元素的值</li></ul><p>上述流程与 PySimpleGUI 设计模式部分的代码一一对应。</p><h4 id="gui-布局" tabindex="-1">GUI 布局 <a class="header-anchor" href="#gui-布局" aria-label="Permalink to “GUI 布局”">​</a></h4><p>要创建自定义 GUI，首先要将窗体分割成多个行，因为窗体是一行一行定义的。然后，在每一行中从左到右依次放置元素。</p><p>我们得到的就是一个“列表的列表”，类似如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>layout = [  [Text(&#39;Row 1&#39;)],</span></span>
<span class="line"><span>            [Text(&#39;Row 2&#39;), Checkbox(&#39;Checkbox 1&#39;, OK()), Checkbox(&#39;Checkbox 2&#39;), OK()] ]</span></span></code></pre></div><p>上述布局对应的效果如下：</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-custom-form.jpg" alt=""></p><h3 id="展示-gui" tabindex="-1">展示 GUI <a class="header-anchor" href="#展示-gui" aria-label="Permalink to “展示 GUI”">​</a></h3><p>当你完成布局、拷贝完用于创建和展示窗体的代码后，下一步就是展示窗体并收集用户数据。</p><p>下面这行代码用于展示窗体并返回收集的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span></code></pre></div><p>窗体返回的结果由两部分组成：一部分是被点击按钮的名称，另一部分是一个列表，包含所有用户输入窗体的值。</p><p>在这个例子中，窗体显示后用户直接点击 “OK” 按钮，返回的结果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>button == &#39;OK&#39;</span></span>
<span class="line"><span>values == [False, False]</span></span></code></pre></div><p>Checkbox 类型元素返回 <code>True</code> 或 <code>False</code> 类型的值。由于默认处于未选中状态，两个元素的值都是 <code>False</code>。</p><h3 id="显示元素的值" tabindex="-1">显示元素的值 <a class="header-anchor" href="#显示元素的值" aria-label="Permalink to “显示元素的值”">​</a></h3><p>一旦从 GUI 获取返回值，检查返回变量中的值是个不错的想法。与其使用 <code>print</code> 语句进行打印，我们不妨坚持使用 GUI 并在一个窗口中输出这些值。</p><p>（LCTT 译注：考虑使用的是 Python 3 版本，<code>print</code> 应该是函数而不是语句。）</p><p>在 PySimpleGUI 中，有多种消息框可供选取。传递给消息框（函数）的数据会被显示在消息框中；函数可以接受任意数目的参数，你可以轻松的将所有要查看的变量展示出来。</p><p>在 PySimpleGUI 中，最常用的消息框是 <code>MsgBox</code>。要展示上面例子中的数据，只需编写一行代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MsgBox(&#39;The GUI returned:&#39;, button, values)</span></span></code></pre></div><h3 id="整合" tabindex="-1">整合 <a class="header-anchor" href="#整合" aria-label="Permalink to “整合”">​</a></h3><p>好了，你已经了解了基础知识，让我们创建一个包含尽可能多 PySimpleGUI 元素的窗体吧！此外，为了更好的感观效果，我们将采用绿色/棕褐色的配色方案。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sg.ChangeLookAndFeel(&#39;GreenTan&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form = sg.FlexForm(&#39;Everything bagel&#39;, default_element_size=(40, 1))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>column1 = [[sg.Text(&#39;Column 1&#39;, background_color=&#39;#d3dfda&#39;, justification=&#39;center&#39;, size=(10,1))],</span></span>
<span class="line"><span>           [sg.Spin(values=(&#39;Spin Box 1&#39;, &#39;2&#39;, &#39;3&#39;), initial_value=&#39;Spin Box 1&#39;)],</span></span>
<span class="line"><span>           [sg.Spin(values=(&#39;Spin Box 1&#39;, &#39;2&#39;, &#39;3&#39;), initial_value=&#39;Spin Box 2&#39;)],</span></span>
<span class="line"><span>           [sg.Spin(values=(&#39;Spin Box 1&#39;, &#39;2&#39;, &#39;3&#39;), initial_value=&#39;Spin Box 3&#39;)]]</span></span>
<span class="line"><span>layout = [</span></span>
<span class="line"><span>    [sg.Text(&#39;All graphic widgets in one form!&#39;, size=(30, 1), font=(&quot;Helvetica&quot;, 25))],</span></span>
<span class="line"><span>    [sg.Text(&#39;Here is some text.... and a place to enter text&#39;)],</span></span>
<span class="line"><span>    [sg.InputText(&#39;This is my text&#39;)],</span></span>
<span class="line"><span>    [sg.Checkbox(&#39;My first checkbox!&#39;), sg.Checkbox(&#39;My second checkbox!&#39;, default=True)],</span></span>
<span class="line"><span>    [sg.Radio(&#39;My first Radio!     &#39;, &quot;RADIO1&quot;, default=True), sg.Radio(&#39;My second Radio!&#39;, &quot;RADIO1&quot;)],</span></span>
<span class="line"><span>    [sg.Multiline(default_text=&#39;This is the default Text should you decide not to type anything&#39;, size=(35, 3)),</span></span>
<span class="line"><span>     sg.Multiline(default_text=&#39;A second multi-line&#39;, size=(35, 3))],</span></span>
<span class="line"><span>    [sg.InputCombo((&#39;Combobox 1&#39;, &#39;Combobox 2&#39;), size=(20, 3)),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;h&#39;, size=(34, 20), default_value=85)],</span></span>
<span class="line"><span>    [sg.Listbox(values=(&#39;Listbox 1&#39;, &#39;Listbox 2&#39;, &#39;Listbox 3&#39;), size=(30, 3)),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;v&#39;, size=(5, 20), default_value=25),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;v&#39;, size=(5, 20), default_value=75),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;v&#39;, size=(5, 20), default_value=10),</span></span>
<span class="line"><span>     sg.Column(column1, background_color=&#39;#d3dfda&#39;)],</span></span>
<span class="line"><span>    [sg.Text(&#39;_&#39;  * 80)],</span></span>
<span class="line"><span>    [sg.Text(&#39;Choose A Folder&#39;, size=(35, 1))],</span></span>
<span class="line"><span>    [sg.Text(&#39;Your Folder&#39;, size=(15, 1), auto_size_text=False, justification=&#39;right&#39;),</span></span>
<span class="line"><span>     sg.InputText(&#39;Default Folder&#39;), sg.FolderBrowse()],</span></span>
<span class="line"><span>    [sg.Submit(), sg.Cancel()]</span></span>
<span class="line"><span>     ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span>
<span class="line"><span>sg.MsgBox(button, values)</span></span></code></pre></div><p>看上面要写不少代码，但如果你试着直接使用 Tkinter 框架实现同样的 GUI，你很快就会发现 PySimpleGUI 版本的代码是多么的简洁。</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-everything.jpg" alt=""></p><p>代码的最后一行打开了一个消息框，效果如下：</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-message-box.jpg" alt=""></p><p>消息框函数中的每一个参数的内容都会被打印到单独的行中。本例的消息框中包含两行，其中第二行非常长而且包含列表嵌套。</p><p>建议花一点时间将上述结果与 GUI 中的元素一一比对，这样可以更好的理解这些结果是如何产生的。</p><h3 id="为你的程序或脚本添加-gui" tabindex="-1">为你的程序或脚本添加 GUI <a class="header-anchor" href="#为你的程序或脚本添加-gui" aria-label="Permalink to “为你的程序或脚本添加 GUI”">​</a></h3><p>如果你有一个命令行方式使用的脚本，添加 GUI 不一定意味着完全放弃该脚本。一种简单的方案如下：如果脚本不需要命令行参数，那么可以直接使用 GUI 调用该脚本；反之，就按原来的方式运行脚本。</p><p>仅需类似如下的逻辑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if len(sys.argv) == 1:</span></span>
<span class="line"><span>        # collect arguments from GUI</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    # collect arguements from sys.argv</span></span></code></pre></div>`,68)),i("p",null,[s[6]||(s[6]=a("创建并运行 GUI 最便捷的方式就是从 ",-1)),e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/cookbook/"},{default:p(()=>[...s[5]||(s[5]=[a("PySimpleGUI 经典实例",-1)])]),_:1}),s[7]||(s[7]=a("中拷贝一份代码并修改。",-1))]),s[29]||(s[29]=l('<p>快来试试吧！给你一直疲于手动执行的脚本增加一些趣味。只需 5-10 分钟即可玩转示例脚本。你可能发现一个几乎满足你需求的经典实例；如果找不到，也很容易自己编写一个。即使你真的玩不转，也只是浪费了 5-10 分钟而已。</p><h3 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h3><h4 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to “安装方式”">​</a></h4><p>支持 Tkinter 的系统就支持 PySimpleGUI，甚至包括<ruby>树莓派<rt>Raspberry Pi</rt></ruby>，但你需要使用 Python 3。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install PySimpleGUI</span></span></code></pre></div><h4 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to “文档”">​</a></h4>',6)),i("ul",null,[i("li",null,[e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/"},{default:p(()=>[...s[8]||(s[8]=[a("手册",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/cookbook/"},{default:p(()=>[...s[9]||(s[9]=[a("经典实例",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://github.com/MikeTheWatchGuy/PySimpleGUI"},{default:p(()=>[...s[10]||(s[10]=[a("GitHub repository",-1)])]),_:1})])]),s[30]||(s[30]=i("hr",null,null,-1)),i("p",null,[s[12]||(s[12]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/18/8/pysimplegui"},{default:p(()=>[...s[11]||(s[11]=[a("https://opensource.com/article/18/8/pysimplegui",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/pysimplegui"},{default:p(()=>[...s[13]||(s[13]=[a("Mike Barnett",-1)])]),_:1}),s[18]||(s[18]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[14]||(s[14]=[a("lujun9972",-1)])]),_:1}),s[19]||(s[19]=a(" 译者：",-1)),e(n,{href:"https://github.com/pinewall"},{default:p(()=>[...s[15]||(s[15]=[a("pinewall",-1)])]),_:1}),s[20]||(s[20]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[22]||(s[22]=[a("Linux中国",-1)])]),_:1}),s[25]||(s[25]=a(" 荣誉推出",-1))])])}const x=t(u,[["render",h]]);export{I as __pageData,x as default};
